from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import CommercialFleetVehicle

class VehicleStatusDirectUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, vehicle_id):
        target_state = request.data.get('status')
        if target_state not in CommercialFleetVehicle.STATUS:
            return Response({'error': 'Invalid vehicle state'}, status=status.HTTP_400_BAD_REQUEST)

        # Restrict update operation to vehicles owned by the authenticated user's carrier company
        rows_updated = CommercialFleetVehicle.objects.filter(
            id=vehicle_id,
            carrier_company=request.user.carrier_company
        ).update(status=target_state)
        if not rows_updated:
            return Response({'error': 'Vehicle not found'}, status=status.HTTP_404_NOT_FOUND)

        return Response({'status': 'State updated', 'vehicle_id': vehicle_id, 'new_status': target_state})
